<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess, SplitIdStringsFromText } from "@/util/tips";
import {
  GetPermissionGroupList,
  GetPermissionGroupMemberList,
  PostPermissionGroupMemberSave,
} from "@/apis/permission";
import { PostUserParse } from "@/apis/user";
import type { GroupMember, UserGroupInfo } from "@/types/permission";

const { globalProperties } = useCurrentInstance();

const groups = ref([] as UserGroupInfo[]);
const selectedGroupId = ref<number | undefined>(undefined);
const keyword = ref("");
const loading = ref(false);
const members = ref([] as GroupMember[]);
const total = ref(0);
const page = ref(1);
const pageSize = ref(20);

const groupOptions = computed(() =>
  groups.value.map((group) => ({
    value: group.id,
    label: `${group.name || group.key}（${group.member_count} 人）`,
  }))
);

const selectedGroup = computed(() =>
  groups.value.find((group) => group.id === selectedGroupId.value)
);

const loadGroups = async () => {
  const res = await GetPermissionGroupList();
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  groups.value = res.data ?? [];
  if (selectedGroupId.value === undefined && groups.value.length > 0) {
    selectedGroupId.value = groups.value[0].id;
  }
};

const loadMembers = async () => {
  if (selectedGroupId.value === undefined) {
    members.value = [];
    total.value = 0;
    return;
  }
  loading.value = true;
  try {
    const res = await GetPermissionGroupMemberList(
      selectedGroupId.value,
      keyword.value.trim(),
      page.value,
      pageSize.value
    );
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    members.value = res.data?.list ?? [];
    total.value = res.data?.total ?? 0;
  } finally {
    loading.value = false;
  }
};

onMounted(async () => {
  await loadGroups();
  await loadMembers();
});

watch(selectedGroupId, () => {
  page.value = 1;
  loadMembers();
});

watch(page, loadMembers);
watch(pageSize, () => {
  page.value = 1;
  loadMembers();
});

const handleSearch = () => {
  page.value = 1;
  loadMembers();
};

// ===== 添加成员 =====

const addVisible = ref(false);
const addInput = ref("");
const adding = ref(false);
/** 上一次解析中未能找到的用户名，用于明确告诉管理员「哪些没加进去」 */
const missingNames = ref([] as string[]);

const openAdd = () => {
  if (selectedGroupId.value === undefined) {
    ShowErrorTips(globalProperties, "请先选择用户组");
    return;
  }
  addInput.value = "";
  missingNames.value = [];
  addVisible.value = true;
};

const handleAdd = async () => {
  if (selectedGroupId.value === undefined) {
    return;
  }
  // 复用项目的分隔约定（空白 + 英文逗号），额外把中文逗号也视为分隔符——
  // 管理员常常是从中文文档里粘一份名单过来。
  // 该工具函数名字里带 Id，但实现（strings.Fields 语义 + 逗号拆分 + 去空）与本场景
  // 完全一致，因此复用而不是再写一份。
  const names = SplitIdStringsFromText(addInput.value.replace(/，/g, ","));
  if (names.length === 0) {
    ShowErrorTips(globalProperties, "请输入要添加的用户名");
    return;
  }
  adding.value = true;
  try {
    const parsed = await PostUserParse(names);
    if (parsed.code !== 0) {
      ShowErrorTips(globalProperties, parsed.code);
      return;
    }
    // PostUserParse 走的是未类型化的既有接口（apis/user.ts 未标注返回类型），
    // 这里就地收窄成组成员形状，避免下游出现隐式 any
    const users = (parsed.data?.users ?? []) as GroupMember[];
    if (users.length === 0) {
      missingNames.value = names;
      ShowErrorTips(globalProperties, "这些用户名都没有找到对应的用户");
      return;
    }
    // 后端只返回找得到的用户，因此差集就是没找到的
    const foundNames = new Set(users.map((user) => user.username));
    missingNames.value = names.filter((name) => !foundNames.has(name));

    const res = await PostPermissionGroupMemberSave({
      group_id: selectedGroupId.value,
      add_user_ids: users.map((user) => user.id),
      remove_user_ids: [],
    });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(
      globalProperties,
      missingNames.value.length > 0
        ? `已添加 ${users.length} 人，另有 ${missingNames.value.length} 个用户名未找到`
        : `已添加 ${users.length} 人`
    );
    if (missingNames.value.length === 0) {
      addVisible.value = false;
    }
    await loadGroups();
    await loadMembers();
  } finally {
    adding.value = false;
  }
};

const handleRemove = async (row: GroupMember) => {
  if (selectedGroupId.value === undefined) {
    return;
  }
  const res = await PostPermissionGroupMemberSave({
    group_id: selectedGroupId.value,
    add_user_ids: [],
    remove_user_ids: [row.id],
  });
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  ShowTextTipsSuccess(globalProperties, "已移出该组");
  await loadGroups();
  await loadMembers();
};
</script>

<template>
  <div class="permission-panel">
    <div class="panel-toolbar">
      <t-select
        v-model="selectedGroupId"
        :options="groupOptions"
        placeholder="选择用户组"
        style="width: 260px"
      />
      <t-input
        v-model="keyword"
        placeholder="按用户名或昵称搜索"
        style="width: 220px"
        clearable
        @enter="handleSearch"
        @clear="handleSearch"
      />
      <t-button variant="outline" @click="handleSearch">搜索</t-button>
      <t-button theme="primary" :disabled="selectedGroupId === undefined" @click="openAdd">
        添加成员
      </t-button>
    </div>

    <t-alert v-if="selectedGroup" theme="info" :message="`当前组：${selectedGroup.name || selectedGroup.key}`">
      <template #message>
        <span>
          当前组：{{ selectedGroup.name || selectedGroup.key }}；绑定角色：
          <template v-if="selectedGroup.roles.length === 0">无（组内成员不会有额外权限）</template>
          <template v-else>{{ selectedGroup.roles.join("、") }}</template>
        </span>
      </template>
    </t-alert>

    <t-table
      row-key="id"
      :data="members"
      :loading="loading"
      :scroll="{ x: 600 }"
      :columns="[
        { title: '用户名', colKey: 'username', width: 200 },
        { title: '昵称', colKey: 'nickname', width: 220 },
        { title: '操作', colKey: 'op', width: 100, fixed: 'right' },
      ]"
    >
      <template #op="{ row }">
        <t-popconfirm content="移出该组后，他将失去这个组带来的角色与权限。" @confirm="handleRemove(row)">
          <t-link theme="danger">移出</t-link>
        </t-popconfirm>
      </template>
    </t-table>

    <div class="panel-pagination">
      <t-pagination
        v-model="page"
        v-model:page-size="pageSize"
        :total="total"
        :page-size-options="[10, 20, 50, 100]"
        show-jumper
      />
    </div>

    <t-dialog
      v-model:visible="addVisible"
      header="添加成员"
      :confirm-btn="{ loading: adding }"
      width="560px"
      @confirm="handleAdd"
    >
      <t-form label-align="top">
        <t-form-item label="用户名">
          <t-textarea
            v-model="addInput"
            :autosize="{ minRows: 3 }"
            placeholder="可一次输入多个，用逗号、空格或换行分隔"
          />
          <template #help>
            <span>
              添加后，他们将立即继承该组绑定的角色与权限（不需要对方重新登录）。
            </span>
          </template>
        </t-form-item>

        <t-alert v-if="missingNames.length > 0" theme="warning" :message="`以下用户名未找到：${missingNames.join('、')}`" />
      </t-form>
    </t-dialog>
  </div>
</template>

<style scoped>
.panel-toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.panel-pagination {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}
</style>
