<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess } from "@/util/tips";
import {
  GetPermissionGroupList,
  GetPermissionRoleList,
  PostPermissionGroupDelete,
  PostPermissionGroupSave,
} from "@/apis/permission";
import type { GroupSaveRequest, RoleInfo, UserGroupInfo } from "@/types/permission";

const { globalProperties } = useCurrentInstance();

const loading = ref(false);
const groups = ref([] as UserGroupInfo[]);
const roles = ref([] as RoleInfo[]);

const roleNameByKey = computed(() => {
  const map: Record<string, string> = {};
  for (const role of roles.value) {
    map[role.key] = role.name || role.key;
  }
  return map;
});

const roleOptions = computed(() =>
  roles.value.map((role) => ({
    value: role.key,
    label: role.is_super ? `${role.name || role.key}（超管）` : role.name || role.key,
  }))
);

const loadGroups = async () => {
  loading.value = true;
  try {
    const res = await GetPermissionGroupList();
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    groups.value = res.data ?? [];
  } finally {
    loading.value = false;
  }
};

const loadRoles = async () => {
  const res = await GetPermissionRoleList();
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  roles.value = res.data ?? [];
};

onMounted(async () => {
  await Promise.all([loadRoles(), loadGroups()]);
});

// ===== 编辑 =====

const editVisible = ref(false);
const saving = ref(false);
const editForm = ref({} as GroupSaveRequest);

const editTitle = computed(() => (editForm.value.id > 0 ? "编辑用户组" : "新建用户组"));
const editingBuiltin = computed(() => {
  const group = groups.value.find((item) => item.id === editForm.value.id);
  return group?.is_builtin === true;
});

const openCreate = () => {
  editForm.value = {
    id: 0,
    key: "",
    name: "",
    description: "",
    sort: 0,
    roles: [],
  };
  editVisible.value = true;
};

const openEdit = (row: UserGroupInfo) => {
  editForm.value = {
    id: row.id,
    key: row.key,
    name: row.name,
    description: row.description,
    sort: row.sort,
    roles: [...row.roles],
  };
  editVisible.value = true;
};

const handleSave = async () => {
  if (!editForm.value.name.trim()) {
    ShowErrorTips(globalProperties, "请填写用户组名称");
    return;
  }
  if (editForm.value.id <= 0 && !editForm.value.key.trim()) {
    ShowErrorTips(globalProperties, "请填写用户组标识");
    return;
  }
  saving.value = true;
  try {
    const res = await PostPermissionGroupSave(editForm.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "已保存");
    editVisible.value = false;
    await loadGroups();
  } finally {
    saving.value = false;
  }
};

const handleDelete = async (row: UserGroupInfo) => {
  const res = await PostPermissionGroupDelete(row.id);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  ShowTextTipsSuccess(globalProperties, "已删除");
  await loadGroups();
};

const groupRoleTags = (row: UserGroupInfo) => {
  if (row.roles.length === 0) {
    return ["未绑定角色"];
  }
  return row.roles.map((key) => roleNameByKey.value[key] ?? key);
};
</script>

<template>
  <div class="permission-panel">
    <div class="panel-toolbar">
      <t-button theme="primary" @click="openCreate">新建用户组</t-button>
      <span class="panel-hint">
        用户组用于批量授权：给组绑定角色，组内成员共同继承。新增成员只需加入组，无需逐个授权。
      </span>
    </div>

    <t-table
      row-key="id"
      :data="groups"
      :loading="loading"
      :scroll="{ x: 900 }"
      :columns="[
        { title: '标识', colKey: 'key', width: 160 },
        { title: '名称', colKey: 'name', width: 160 },
        { title: '说明', colKey: 'description', width: 220, ellipsis: true },
        { title: '绑定角色', colKey: 'roles', width: 280 },
        { title: '成员', colKey: 'member_count', width: 90 },
        { title: '操作', colKey: 'op', width: 140, fixed: 'right' },
      ]"
    >
      <template #key="{ row }">
        <t-space size="small">
          <span>{{ row.key }}</span>
          <t-tag v-if="row.is_builtin" theme="default" size="small" variant="light">内置</t-tag>
        </t-space>
      </template>

      <template #roles="{ row }">
        <t-space size="small" break-line>
          <t-tag
            v-for="tag in groupRoleTags(row)"
            :key="tag"
            size="small"
            variant="light"
            :theme="row.roles.length === 0 ? 'default' : 'primary'"
          >
            {{ tag }}
          </t-tag>
        </t-space>
      </template>

      <template #op="{ row }">
        <t-space size="small">
          <t-link theme="primary" @click="openEdit(row)">编辑</t-link>
          <t-popconfirm
            content="删除用户组会同时解除它的角色绑定与全部成员关系，组内用户将失去这些角色带来的权限。"
            @confirm="handleDelete(row)"
          >
            <t-link theme="danger">删除</t-link>
          </t-popconfirm>
        </t-space>
      </template>
    </t-table>

    <t-dialog
      v-model:visible="editVisible"
      :header="editTitle"
      :confirm-btn="{ loading: saving }"
      width="560px"
      @confirm="handleSave"
    >
      <t-form label-align="top">
        <t-form-item label="标识（key）">
          <t-input
            v-model="editForm.key"
            :disabled="editForm.id > 0 && editingBuiltin"
            placeholder="如 g-assistant-2024"
          />
          <template #help>
            <span v-if="editForm.id > 0 && editingBuiltin">内置用户组的标识不可修改。</span>
            <span v-else-if="editForm.id > 0">标识是稳定字段，编辑时不可修改。</span>
          </template>
        </t-form-item>

        <t-form-item label="名称">
          <t-input v-model="editForm.name" placeholder="如 2024 级助教" />
        </t-form-item>

        <t-form-item label="说明">
          <t-textarea v-model="editForm.description" :autosize="{ minRows: 2 }" />
        </t-form-item>

        <t-form-item label="排序">
          <t-input-number v-model="editForm.sort" :min="0" />
        </t-form-item>

        <t-form-item label="绑定角色">
          <t-select
            v-model="editForm.roles"
            :options="roleOptions"
            multiple
            clearable
            placeholder="选择该组要继承的角色"
          />
          <template #help>
            绑定超管角色等于把全部权限授予组内所有人，请谨慎操作。
          </template>
        </t-form-item>
      </t-form>
    </t-dialog>
  </div>
</template>

<style scoped>
.panel-toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.panel-hint {
  color: var(--td-text-color-secondary);
  font-size: 13px;
}
</style>
