<script setup lang="ts">
import { ref } from "vue";
import RolePanel from "@/views/permission/RolePanel.vue";
import GroupPanel from "@/views/permission/GroupPanel.vue";
import MemberPanel from "@/views/permission/MemberPanel.vue";
import UserPanel from "@/views/permission/UserPanel.vue";
import AuditPanel from "@/views/permission/AuditPanel.vue";

/**
 * 权限管理主页面（「管理」tab 下的一个子页）。
 *
 * 五个功能放在同一个页面的 tab 里，而不是拆成五个 sidebar 项：它们是同一件事的不同侧面
 * （角色 → 组 → 成员 → 授权 → 审计），排障时经常要在「这个角色被谁用了」与
 * 「这个用户的权限哪来的」之间来回跳，拆成页面会让侧边栏变长且切换更慢。
 *
 * 每个 tab 都带 lazy：tdesign 的 tab-panel 默认在挂载时就渲染全部面板，于是打开本页会
 * 立刻触发五个面板各自的 onMounted 请求（角色/用户组/用户授权三个面板还会重复拉同一份
 * 角色与用户组清单）。lazy 让面板在**首次切到**时才挂载，之后保持挂载以保留状态。
 */
const activeTab = ref("role");
</script>

<template>
  <div class="manage-permission">
    <t-tabs v-model="activeTab">
      <t-tab-panel value="role" label="角色" lazy>
        <RolePanel />
      </t-tab-panel>
      <t-tab-panel value="group" label="用户组" lazy>
        <GroupPanel />
      </t-tab-panel>
      <t-tab-panel value="member" label="组成员" lazy>
        <MemberPanel />
      </t-tab-panel>
      <t-tab-panel value="user" label="用户授权" lazy>
        <UserPanel />
      </t-tab-panel>
      <t-tab-panel value="audit" label="变更审计" lazy>
        <AuditPanel />
      </t-tab-panel>
    </t-tabs>
  </div>
</template>

<style scoped>
.manage-permission {
  padding: 0 4px;
}
</style>
