<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess } from "@/util/tips";
import {
  GetPermissionCatalog,
  GetPermissionGroupList,
  GetPermissionRoleList,
  GetPermissionUserAuth,
  PostPermissionUserGroupSave,
  PostPermissionUserRoleSave,
} from "@/apis/permission";
import { PostUserParse } from "@/apis/user";
import { useUserStore } from "@/stores/user";
import type { PermissionGroup, RoleInfo, UserAuthInfo, UserGroupInfo } from "@/types/permission";

const { globalProperties } = useCurrentInstance();
const userStore = useUserStore();

const searchName = ref("");
const loading = ref(false);
const savingRoles = ref(false);
const savingGroups = ref(false);

const auth = ref(null as UserAuthInfo | null);
const roles = ref([] as RoleInfo[]);
const groups = ref([] as UserGroupInfo[]);
const catalog = ref([] as PermissionGroup[]);

// 编辑中的本地副本：改完点保存才提交，避免误触即生效
const directRoles = ref([] as string[]);
const groupIds = ref([] as number[]);

const permissionNames = computed(() => {
  const map: Record<string, string> = {};
  for (const group of catalog.value) {
    for (const item of group.items) {
      map[item.key] = item.name;
    }
  }
  return map;
});

const roleOptions = computed(() =>
  roles.value.map((role) => ({
    value: role.key,
    label: role.is_super ? `${role.name || role.key}（超管）` : role.name || role.key,
  }))
);

const groupOptions = computed(() =>
  groups.value.map((group) => ({
    value: group.id,
    label: `${group.name || group.key}（${group.roles.length} 个角色）`,
  }))
);

/** 是否在编辑自己的授权：后端会拒绝（防自提权），前端提前提示以免白跑一次请求 */
const isSelf = computed(() => auth.value !== null && auth.value.user_id === userStore.getUserId);

/** 组继承来的角色（有效角色里减去直接授予的），用于向管理员说明「权限从哪来」 */
const inheritedRoles = computed(() => {
  if (auth.value === null) {
    return [];
  }
  const direct = new Set(auth.value.direct_roles);
  return auth.value.roles.filter((key) => !direct.has(key));
});

const loadOptions = async () => {
  const [roleRes, groupRes, catalogRes] = await Promise.all([
    GetPermissionRoleList(),
    GetPermissionGroupList(),
    GetPermissionCatalog(),
  ]);
  if (roleRes.code === 0) {
    roles.value = roleRes.data ?? [];
  }
  if (groupRes.code === 0) {
    groups.value = groupRes.data ?? [];
  }
  if (catalogRes.code === 0) {
    catalog.value = catalogRes.data?.groups ?? [];
  }
};

onMounted(loadOptions);

const handleSearch = async () => {
  const name = searchName.value.trim();
  if (!name) {
    ShowErrorTips(globalProperties, "请输入用户名");
    return;
  }
  loading.value = true;
  try {
    const parsed = await PostUserParse([name]);
    if (parsed.code !== 0) {
      ShowErrorTips(globalProperties, parsed.code);
      return;
    }
    // 同 MemberPanel：PostUserParse 未标注返回类型，就地收窄
    const users = (parsed.data?.users ?? []) as { id: number; username: string }[];
    if (users.length === 0) {
      auth.value = null;
      ShowErrorTips(globalProperties, `未找到用户「${name}」`);
      return;
    }
    const res = await GetPermissionUserAuth(users[0].id);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    auth.value = res.data;
    directRoles.value = [...(res.data?.direct_roles ?? [])];
    groupIds.value = [...(res.data?.group_ids ?? [])];
  } finally {
    loading.value = false;
  }
};

/** 重新拉取该用户的授权（保存后刷新，让「有效权限」立即反映最新状态） */
const reloadAuth = async () => {
  if (auth.value === null) {
    return;
  }
  const res = await GetPermissionUserAuth(auth.value.user_id);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  auth.value = res.data;
  directRoles.value = [...(res.data?.direct_roles ?? [])];
  groupIds.value = [...(res.data?.group_ids ?? [])];
};

const handleSaveRoles = async () => {
  if (auth.value === null) {
    return;
  }
  savingRoles.value = true;
  try {
    const res = await PostPermissionUserRoleSave({
      user_id: auth.value.user_id,
      roles: directRoles.value,
    });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "直接角色已保存");
    await reloadAuth();
  } finally {
    savingRoles.value = false;
  }
};

const handleSaveGroups = async () => {
  if (auth.value === null) {
    return;
  }
  savingGroups.value = true;
  try {
    const res = await PostPermissionUserGroupSave({
      user_id: auth.value.user_id,
      group_ids: groupIds.value,
    });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "所属用户组已保存");
    await reloadAuth();
  } finally {
    savingGroups.value = false;
  }
};
</script>

<template>
  <div class="permission-panel">
    <div class="panel-toolbar">
      <t-input
        v-model="searchName"
        placeholder="输入用户名后回车查询"
        style="width: 260px"
        clearable
        @enter="handleSearch"
      />
      <t-button theme="primary" :loading="loading" @click="handleSearch">查询授权</t-button>
      <span class="panel-hint">按用户名查询某人的直接角色、所属用户组与最终生效的权限点。</span>
    </div>

    <template v-if="auth !== null">
      <t-alert v-if="isSelf" theme="warning" class="self-alert">
        <template #message>
          这是你自己的账号。为避免自提权，系统<strong>不允许</strong>任何人修改自己的授权
          （保存会被拒绝），请让另一位管理员代为操作。
        </template>
      </t-alert>

      <t-card :title="`${auth.nickname || auth.username}（${auth.username}）`" class="auth-card">
        <template #actions>
          <t-space size="small">
            <t-tag v-if="auth.is_super" theme="warning" variant="light">超级管理员</t-tag>
          </t-space>
        </template>

        <t-form label-align="top">
          <t-form-item label="直接授予的角色">
            <t-select
              v-model="directRoles"
              :options="roleOptions"
              multiple
              clearable
              placeholder="不选择表示没有直接角色"
              :disabled="isSelf"
            />
            <template #help>
              只包含「直接授予本人」的角色；通过用户组继承的角色请在下方维护。
            </template>
          </t-form-item>

          <div class="form-actions">
            <t-button
              theme="primary"
              size="small"
              :loading="savingRoles"
              :disabled="isSelf"
              @click="handleSaveRoles"
            >
              保存直接角色
            </t-button>
          </div>

          <t-divider />

          <t-form-item label="所属用户组">
            <t-select
              v-model="groupIds"
              :options="groupOptions"
              multiple
              clearable
              placeholder="不选择表示不属于任何用户组"
              :disabled="isSelf"
            />
            <template #help>
              用户组带来的角色同样计入有效权限；把一个高权限组加给某人前请确认影响面。
            </template>
          </t-form-item>

          <div class="form-actions">
            <t-button
              theme="primary"
              size="small"
              :loading="savingGroups"
              :disabled="isSelf"
              @click="handleSaveGroups"
            >
              保存所属用户组
            </t-button>
          </div>
        </t-form>

        <t-divider>最终生效</t-divider>

        <div class="effective">
          <div class="effective-row">
            <span class="effective-label">有效角色</span>
            <t-space size="small" break-line>
              <t-tag v-for="key in auth.roles" :key="key" size="small" variant="light">
                {{ key }}
              </t-tag>
              <span v-if="auth.roles.length === 0" class="empty-text">无</span>
            </t-space>
          </div>

          <div v-if="inheritedRoles.length > 0" class="effective-row">
            <span class="effective-label">其中继承自用户组</span>
            <t-space size="small" break-line>
              <t-tag
                v-for="key in inheritedRoles"
                :key="key"
                size="small"
                theme="primary"
                variant="light"
              >
                {{ key }}
              </t-tag>
            </t-space>
          </div>

          <div class="effective-row">
            <span class="effective-label">有效权限点</span>
            <t-space size="small" break-line>
              <t-tag
                v-for="key in auth.permissions"
                :key="key"
                size="small"
                theme="success"
                variant="light"
              >
                {{ permissionNames[key] ?? key }}
              </t-tag>
              <span v-if="auth.permissions.length === 0" class="empty-text">无</span>
            </t-space>
          </div>
        </div>
      </t-card>
    </template>

    <t-empty v-else description="输入用户名查询该用户的授权情况" />
  </div>
</template>

